<template>
  <transition name="slide-down">
    <div v-if="isVisible" class="review-banner">
      <div class="banner-content">
        <div class="banner-icon">
          <i class="fas fa-star"></i>
        </div>
        <div class="banner-text">
          <h3 class="banner-title">Review 2025 is Ready!</h3>
          <p class="banner-description">Check out our 2025 progress</p>
        </div>
        <router-link to="/review-2025" class="banner-button" @click="handleViewClick">
          <span>View Review</span>
          <i class="fas fa-arrow-right"></i>
        </router-link>
        <button @click="closeBanner" class="banner-close" aria-label="Close">
          <i class="fas fa-times"></i>
        </button>
      </div>
    </div>
  </transition>
</template>

<script setup>
import { ref, computed } from 'vue'
import { useRoute } from 'vue-router'

const route = useRoute()

// Check localStorage synchronously on initialization to prevent flash
const wasClosed = typeof window !== 'undefined' ? localStorage.getItem('review2025BannerClosed') === 'true' : false
const isClosed = ref(wasClosed)

const isVisible = computed(() => {
  // Don't show on review-2025 page
  if (route.path === '/review-2025') {
    return false
  }
  // Don't show if user closed it
  return !isClosed.value
})

const closeBanner = () => {
  isClosed.value = true
  // Save to localStorage so it doesn't show again
  if (typeof window !== 'undefined') {
    localStorage.setItem('review2025BannerClosed', 'true')
  }
}

const handleViewClick = () => {
  // Save to localStorage when user clicks "View Review"
  if (typeof window !== 'undefined') {
    localStorage.setItem('review2025BannerClosed', 'true')
  }
  isClosed.value = true
}
</script>

